using UnityEngine;

// ScriptExecutionOrder 决定类在 Update 链中的相对顺序
[DefaultExecutionOrder(-100)]
public class GameManager : MonoBehaviour
{
    public static GameManager Instance { get; private set; }

    void Awake()
    {
        // 单例：先于玩家控制器执行
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    void OnEnable()  { Debug.Log("[GM] OnEnable"); }
    void Start()     { Debug.Log("[GM] Start —— 此时所有 Awake 都已跑完"); }
    void OnDisable() { Debug.Log("[GM] OnDisable"); }
    void OnDestroy() { Debug.Log("[GM] OnDestroy"); }
}

public class Player : MonoBehaviour
{
    [SerializeField] float moveSpeed = 5f;
    Rigidbody _rb;
    Vector3 _input;

    void Awake()
    {
        _rb = GetComponent<Rigidbody>();
        // 在 Inspector 里拖引用，或用 [RequireComponent] 强制存在
    }

    void OnEnable()
    {
        // 成对订阅，避免泄漏
        GameManager.Instance.SomeEvent += HandleEvent;
    }

    void OnDisable()
    {
        if (GameManager.Instance != null)
            GameManager.Instance.SomeEvent -= HandleEvent;
    }

    void Update()
    {
        // 每帧读取输入
        _input = new Vector3(Input.GetAxisRaw("Horizontal"), 0, Input.GetAxisRaw("Vertical"));
    }

    void FixedUpdate()
    {
        // 物理操作必须放在 FixedUpdate
        _rb.MovePosition(_rb.position + _input.normalized * moveSpeed * Time.fixedDeltaTime);
    }

    void LateUpdate()
    {
        // 相机跟随写在 LateUpdate，保证被跟随对象的 Update 已完成
        // Camera.main.transform.position = transform.position + new Vector3(0, 5, -10);
    }

    void HandleEvent() { /* ... */ }
}

