// 1) Serializable 容器：嵌套结构在 Inspector 中展开
[Serializable]
public class StatBlock
{
    public int hp = 100;
    public int mp = 50;
    public float moveSpeed = 3.5f;
}

[Serializable]
public struct LootEntry
{
    public string id;
    public int min, max;
    public float weight;
}

public class Enemy : MonoBehaviour
{
    // 2) private + SerializeField：Inspector 可见，外部不能改
    [SerializeField] int _level = 1;
    [SerializeField] StatBlock _stats = new();
    [SerializeField] LootEntry[] _lootTable;

    // 3) FormerlySerializedAs：字段改名后保留历史数据
    [SerializeField, FormerlySerializedAs("damage")]
    int _attackDamage;

    // 4) SerializeReference：序列化接口/抽象类型
    [Serializable]
    public abstract class AttackBehavior { public abstract void Execute(Enemy self); }

    [Serializable]
    public class MeleeAttack : AttackBehavior
    {
        public float range = 1.5f;
        public override void Execute(Enemy self) { /* 近战逻辑 */ }
    }

    [Serializable]
    public class RangedAttack : AttackBehavior
    {
        public GameObject projectile;
        public override void Execute(Enemy self) { /* 远程逻辑 */ }
    }

    // SerializeReference 让 _attack 可以指向 MeleeAttack 或 RangedAttack 实例
    [SerializeReference] AttackBehavior _attack = new MeleeAttack();

    // 5) NonSerialized：public 字段不参与序列化（运行时临时值）
    [NonSerialized] public int RuntimeHp;

    void Awake()
    {
        // _stats.hp 来自 Inspector，运行时再拷一份避免污染 Prefab
        RuntimeHp = _stats.hp;
        _attack?.Execute(this);
    }
}

