// 2) 数据库：聚合所有技能，提供运行时查询
[CreateAssetMenu(menuName = "Game/Skill Database", fileName = "SkillDatabase")]
public class SkillDatabase : ScriptableObject
{
    public List<SkillData> all = new();
    Dictionary<string, SkillData> _index;

    void OnEnable()
    {
        // 运行时构建索引，避免每帧 List.Find
        _index = new Dictionary<string, SkillData>(all.Count);
        foreach (var s in all)
            if (s != null && !_index.ContainsKey(s.id))
                _index[s.id] = s;
    }

    public SkillData Get(string id) =>
        _index != null && _index.TryGetValue(id, out var s) ? s : null;
}

