// ========== 3) EventBus：全局发布订阅 ==========
public static class EventBus
{
    static readonly Dictionary<Type, List<object>> _subs = new();

    public static void Subscribe<T>(Action<T> handler)
    {
        if (!_subs.TryGetValue(typeof(T), out var list))
            _subs[typeof(T)] = list = new List<object>();
        list.Add(handler);
    }
    public static void Unsubscribe<T>(Action<T> handler)
    {
        if (_subs.TryGetValue(typeof(T), out var list))
            list.Remove(handler);
    }
    public static void Publish<T>(T payload)
    {
        if (!_subs.TryGetValue(typeof(T), out var list)) return;
        // 拷贝一份：避免回调内订阅/反订阅破坏遍历
        var copy = list.ToArray();
        foreach (var obj in copy)
            ((Action<T>)obj).Invoke(payload);
    }
}

