using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

public class HeroLoader : MonoBehaviour
{
    [SerializeField] AssetReferenceGameObject _heroRef;   // Inspector 拖
    AsyncOperationHandle<GameObject> _preloadHandle;
    GameObject _spawned;

    async void Start()
    {
        // 1) 预加载（不实例化）：常用于切换场景前预热
        _preloadHandle = _heroRef.LoadAssetAsync<GameObject>();
        await _preloadHandle.Task;
        if (_preloadHandle.Status != AsyncOperationStatus.Succeeded)
        {
            Debug.LogError($"加载失败：{_preloadHandle.OperationException}");
            return;
        }
        Spawn();
    }

    void Spawn()
    {
        // 2) 实例化（Addressables.InstantiateAsync 内部 ref++）
        _spawned = Instantiate(_preloadHandle.Result, transform);
    }

    void OnDestroy()
    {
        // 3) 释放顺序：先销毁实例，再释放 Asset
        if (_spawned != null) Destroy(_spawned);
        if (_preloadHandle.IsValid()) Addressables.Release(_preloadHandle);
    }

    // ========== 进阶：按字符串 Key 加载 + 进度回调 ==========
    public void LoadWithProgress(string address)
    {
        var handle = Addressables.LoadAssetAsync<Sprite>(address);
        handle.Completed += op => Debug.Log($"完成：{op.Result?.name}");
        // 轮询进度（Coroutine 或 async/await 都行）
        StartCoroutine(Watch(handle));
    }
    System.Collections.IEnumerator Watch(AsyncOperationHandle<Sprite> h)
    {
        while (!h.IsDone)
        {
            // PercentComplete 在内部是 0~1 浮点
            Debug.Log($"进度 {h.PercentComplete:P0}");
            yield return null;
        }
    }
}

using UnityEngine;
using System.Threading;
using System.Threading.Tasks;
// using Cysharp.Threading.Tasks;  // UniTask

public class AsyncPatterns : MonoBehaviour
{
    [SerializeField] float duration = 1.5f;
    CancellationTokenSource _cts;

    void OnEnable() { _cts = new CancellationTokenSource(); }
    void OnDisable() { _cts?.Cancel(); _cts?.Dispose(); _cts = null; }

    // ========== 1) 协程 ==========
    System.Collections.IEnumerator FadeCo()
    {
        var img = GetComponent<SpriteRenderer>();
        for (float t = 0; t < duration; t += Time.deltaTime)
        {
            var c = img.color;
            c.a = Mathf.Lerp(1, 0, t / duration);
            img.color = c;
            yield return null;
        }
    }

    // ========== 2) async/await（Unity 2023+ Awaitable） ==========
    async Task FadeAsync(CancellationToken ct)
    {
        var img = GetComponent<SpriteRenderer>();
        var start = Time.unscaledTime;
        while (Time.unscaledTime - start < duration)
        {
            ct.ThrowIfCancellationRequested();
            var c = img.color;
            c.a = Mathf.Lerp(1, 0, (Time.unscaledTime - start) / duration);
            img.color = c;
            await Awaitable.NextFrameAsync(ct);
        }
    }

    async void Start()
    {
        try
        {
            await FadeAsync(_cts.Token);
            Debug.Log("淡出完成");
        }
        catch (System.OperationCanceledException) { /* 正常取消 */ }
        catch (System.Exception e) { Debug.LogException(e); }
    }

