// 一个 Renderer Feature：在不透明几何之后绘制自定义 Outline Pass
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class OutlineRendererFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public LayerMask layerMask = -1;
        public Material outlineMaterial;
    }
    public Settings settings = new();
    OutlinePass _pass;

    public override void Create()
    {
        _pass = new OutlinePass(settings) { renderPassEvent = RenderPassEvent.AfterRenderingOpaques };
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData data)
    {
        if (settings.outlineMaterial == null) return;
        _pass.Setup(renderer.cameraColorTargetHandle);
        renderer.EnqueuePass(_pass);
    }

    class OutlinePass : ScriptableRenderPass
    {
        static readonly int _TmpID = Shader.PropertyToID("_OutlineRT");
        Settings _s;
        RTHandle _tmp;

        public OutlinePass(Settings s) { _s = s; ConfigureInput(ScriptableRenderPassInput.Color); }
        public void Setup(RTHandle colorTarget) { }
        public override void OnCameraSetup(CommandBuffer cmd, ref RenderingData data)
        {
            var desc = data.cameraData.cameraTargetDescriptor;
            RenderingUtils.ReAllocateIfNeeded(ref _tmp, desc, name: "_OutlineRT");
            ConfigureTarget(_tmp);
        }
        public override void Execute(ScriptableRenderContext ctx, ref RenderingData data)
        {
            var cmd = CommandBufferPool.Get("OutlinePass");
            // 设置材质、Filter 设置、绘制流程
            // cmd.DrawProcedural(...) 或 cmd.Blit(...) 由具体 outline 算法决定
            ctx.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }
    }
}

// 一个最小、SRP Batcher 兼容的 Unlit URP Shader
Shader "Custom/MyUnlit"
{
    Properties
    {
        [MainColor] _BaseColor ("Base Color", Color) = (1,1,1,1)
        [MainTexture] _BaseMap ("Base Map", 2D) = "white" {}
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" "RenderPipeline"="UniversalPipeline" "Queue"="Geometry" }
        LOD 100

        Pass
        {
            Name "UniversalForward"
            Tags { "LightMode"="UniversalForward" }
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma multi_compile_instancing

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"

            // SRP Batcher 兼容：所有 per-material 变量放进这个 CBUFFER
            CBUFFER_START(UnityPerMaterial)
                float4 _BaseMap_ST;
                half4  _BaseColor;
            CBUFFER_END

            TEXTURE2D(_BaseMap); SAMPLER(sampler_BaseMap);

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv         : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };
            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv          : TEXCOORD0;
                UNITY_VERTEX_INPUT_INSTANCE_ID
            };

            Varyings vert(Attributes IN)
            {
                Varyings OUT;
                UNITY_SETUP_INSTANCE_ID(IN);
                UNITY_TRANSFER_INSTANCE_ID(IN, OUT);
                OUT.positionHCS = TransformObjectToHClip(IN.positionOS.xyz);
                OUT.uv = TRANSFORM_TEX(IN.uv, _BaseMap);
                return OUT;
            }

            half4 frag(Varyings IN) : SV_Target
            {
                UNITY_SETUP_INSTANCE_ID(IN);
                half4 tex = SAMPLE_TEXTURE2D(_BaseMap, sampler_BaseMap, IN.uv);
                return tex * _BaseColor;
            }
            ENDHLSL
        }
    }
}

using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEngine.UI;

public class MiniMapSetup : MonoBehaviour
{
    [SerializeField] Camera _baseCamera;       // 主相机（3D 世界）
    [SerializeField] Camera _minimapCamera;    // 小地图相机
    [SerializeField] RenderTexture _minimapRT; // 200x200 的 RT
    [SerializeField] RawImage _minimapImage;   // UI 显示
    [SerializeField] UniversalRendererData _rendererOverride; // 可选

    void Start()
    {
        // 1) 小地图相机作为 Overlay 堆叠到 Base
        _minimapCamera.GetUniversalAdditionalCameraData().renderType = CameraRenderType.Overlay;
        _baseCamera.GetUniversalAdditionalCameraData().cameraStack.Add(_minimapCamera);
        _baseCamera.GetUniversalAdditionalCameraData().renderShadows = false;

        // 2) 把小地图的渲染结果同时输出到一张 RT（用于截图/录像）
        _minimapCamera.targetTexture = _minimapRT;
        _minimapImage.texture = _minimapRT;

        // 3) 只让小地图相机看"Minimap"层
        _minimapCamera.cullingMask = LayerMask.GetMask("Minimap");
        _baseCamera.cullingMask &= ~LayerMask.GetMask("Minimap"); // 主相机不画
    }
}

// 自定义后处理：灰度 + 描边（用一个 FullScreenPassRendererFeature 装载 Material）
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.RenderGraphModule;
using UnityEngine.Rendering.Universal;

public class GrayscaleFeature : ScriptableRendererFeature
{
    public Material mat;
    GrayscalePass _pass;

    public override void Create()
    {
        _pass = new GrayscalePass(mat) { renderPassEvent = RenderPassEvent.AfterRenderingPostProcessing };
    }
    public override void AddRenderPasses(ScriptableRenderer r, ref RenderingData d)
    {
        if (mat == null) return;
        r.EnqueuePass(_pass);
    }

    class GrayscalePass : ScriptableRenderPass
    {
        Material _m;
        public GrayscalePass(Material m) { _m = m; requiresIntermediateTexture = true; }
        public override void RecordRenderGraph(RenderGraph rg, ContextContainer ctx)
        {
            var resourceData = ctx.Get<UniversalResourceData>();
            var src = resourceData.activeColorTexture;
            var desc = rg.GetTextureDesc(src);
            desc.name = "GrayscaleTemp"; desc.clearBuffer = false;
            var dst = rg.CreateTexture(desc);
            var blit = new RenderGraphUtils.BlitMaterialParameters(src, dst, _m, 0);
            rg.AddBlitPass(blit, "GrayscalePass");
            resourceData.cameraColor = dst;
        }
    }
}

