// 用 LightingSettings API 在 Editor 里自动烘焙
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;

public static class BakeHelper
{
    [MenuItem("Tools/Bake Current Scene")]
    public static void BakeCurrent()
    {
        var scene = SceneManager.GetActiveScene();
        var settings = LightmapSettings.lightingSettings;

        // 1) 调 Lightmap 参数（GPU 烘焙需要 com.unity.rendering.lightmap.d3d12.experimental）
        settings.lightmapMaxSize = 2048;
        settings.filterMode = LightmapFilterMode.PCF;
        LightmapSettings.lightingSettings = settings;

        // 2) 同步烘焙（CI 友好）
        bool ok = Lightmapping.bakeCompleted;
        Lightmapping.bake();
        EditorApplication.update += Wait;
    }
    static void Wait()
    {
        if (Lightmapping.bakeCompleted)
        {
            EditorApplication.update -= Wait;
            AssetDatabase.SaveAssets();
            Debug.Log("烘焙完成");
        }
    }
}

// 一个 Custom Function 节点：柏林噪声扰动 UV
// 文件 Assets/Shaders/Noise.hlsl
float Hash(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}
float ValueNoise(float2 uv)
{
    float2 i = floor(uv);
    float2 f = frac(uv);
    float a = Hash(i);
    float b = Hash(i + float2(1, 0));
    float c = Hash(i + float2(0, 1));
    float d = Hash(i + float2(1, 1));
    float2 u = f * f * (3 - 2 * f);
    return lerp(lerp(a, b, u.x), lerp(c, d, u.x), u.y);
}
