        // 性能：让刚体不睡，连续运动更平滑
        _rb.sleepThreshold = 0.05f;
        _rb.interpolation = RigidbodyInterpolation.Interpolate;
        _rb.collisionDetectionMode = CollisionDetectionMode.Continuous;
    }

    void FixedUpdate()
    {
        // 1) 物理检测：球形射线查地面
        _grounded = Physics.SphereCast(transform.position, 0.3f, Vector3.down,
            out _, 1.1f, _groundMask, QueryTriggerInteraction.Ignore);

        // 2) 移动：在 FixedUpdate 修改 linearVelocity
        var v = _rb.linearVelocity;
        v.x = Input.GetAxisRaw("Horizontal") * 5f;
        v.z = Input.GetAxisRaw("Vertical")   * 5f;
        _rb.linearVelocity = v;

        // 3) 跳跃：AddForce 在 FixedUpdate
        if (_grounded && Input.GetButtonDown("Jump"))
            _rb.AddForce(Vector3.up * _jumpForce, ForceMode.Impulse);
    }

    // 4) Trigger 事件：OnTrigger 仅在 Trigger Collider 上产生
    void OnTriggerEnter(Collider other)
    {
        if (other.TryGetComponent<ICollectible>(out var c))
            c.Collect(gameObject);
    }
}

