[RequireComponent(typeof(CharacterController))]
public class FpsLikeController : MonoBehaviour
{
    [SerializeField] float _walkSpeed = 4.5f;
    [SerializeField] float _sprintSpeed = 7f;
    [SerializeField] float _jumpHeight = 1.4f;
    [SerializeField] float _gravity = -20f;
    [SerializeField] Transform _camera;

    CharacterController _cc;
    Vector3 _velocity;
    bool _grounded;

    void Awake() { _cc = GetComponent<CharacterController>(); }

    void Update()
    {
        // 1) 自检地面：用 SphereCast 兜底
        _grounded = Physics.SphereCast(transform.position + Vector3.up * 0.1f, 0.25f,
            Vector3.down, out _, 0.25f, ~LayerMask.GetMask("Player"), QueryTriggerInteraction.Ignore);

        // 2) 输入
        float h = Input.GetAxisRaw("Horizontal");
        float v = Input.GetAxisRaw("Vertical");
        bool sprint = Input.GetKey(KeyCode.LeftShift);
        float speed = sprint ? _sprintSpeed : _walkSpeed;
        Vector3 wish = (transform.right * h + transform.forward * v).normalized * speed;

        // 3) 平滑水平速度（模拟加减速）
        Vector3 horiz = new Vector3(_velocity.x, 0, _velocity.z);
        horiz = Vector3.Lerp(horiz, wish, 12f * Time.deltaTime);
        _velocity.x = horiz.x;
        _velocity.z = horiz.z;

        // 4) 重力 + 跳跃
        if (_grounded && _velocity.y < 0) _velocity.y = -2f;
        if (_grounded && Input.GetButtonDown("Jump"))
            _velocity.y = Mathf.Sqrt(-2f * _gravity * _jumpHeight);
        _velocity.y += _gravity * Time.deltaTime;

        // 5) 应用位移（注意：Move 输入是本帧位移）
        CollisionFlags flags = _cc.Move(_velocity * Time.deltaTime);
        if ((flags & CollisionFlags.Above) != 0 && _velocity.y > 0)
            _velocity.y = 0;
    }
}

