// StateMachineBehaviour：进入/离开 State 时回调（动画事件钩子）
public class FootstepAudio : StateMachineBehaviour
{
    public AudioClip[] clips;
    public float volume = 0.6f;
    int _lastStep;
    public override void OnStateEnter(Animator a, AnimatorStateInfo s, int layerIndex)
    {
        // 每帧重置触地帧
        _lastStep = -1;
    }
    public override void OnStateUpdate(Animator a, AnimatorStateInfo s, int layerIndex)
    {
        // 走 Run 动画时，规范化时间到整数变化播放脚步声
        int step = Mathf.FloorToInt(s.normalizedTime);
        if (step != _lastStep && a.isHuman)
        {
            _lastStep = step;
            var c = clips[step % clips.Length];
            AudioSource.PlayClipAtPoint(c, a.transform.position, volume);
        }
    }
}

