// 用 PlayableGraph 做一次性受击叠加动画
public class HitAnimBlender : MonoBehaviour
{
    [SerializeField] Animator _animator;
    [SerializeField] AnimationClip _hitClip;
    PlayableGraph _graph;
    AnimationMixerPlayable _mixer;
    AnimationClipPlayable _hit;
    AnimationPlayableOutput _output;
    float _t;
    const float HIT_DURATION = 0.4f;

    void Awake()
    {
        _graph = PlayableGraph.Create("HitBlendGraph");
        _graph.SetTimeUpdateMode(DirectorUpdateMode.GameTime);

        _mixer = AnimationMixerPlayable.Create(_graph, 2);
        _hit   = AnimationClipPlayable.Create(_graph, _hitClip);
        _graph.Connect(_hit, 0, _mixer, 1);
        _mixer.SetInputWeight(0, 1f);    // 通道 0 留给 Animator 输出
        _mixer.SetInputWeight(1, 0f);

        // 把 Animator 的输出接到我们的 mixer 通道 0
        var animSource = AnimatorControllerPlayable.Create(_graph, _animator.runtimeAnimatorController);
        _graph.Connect(animSource, 0, _mixer, 0);
        _output = AnimationPlayableOutput.Create(_graph, "Anim", _animator);
        _output.SetSourcePlayable(_mixer);
        _graph.Play();
    }

    public void PlayHit()
    {
        _t = HIT_DURATION;
        _mixer.SetInputWeight(1, 1f);
    }

    void Update()
    {
        if (_t <= 0) return;
        _t -= Time.deltaTime;
        float w = Mathf.Clamp01(_t / HIT_DURATION);
        _mixer.SetInputWeight(1, w);
        _mixer.SetInputWeight(0, 1f - w * 0.5f);
        if (_t <= 0) { _mixer.SetInputWeight(1, 0f); _mixer.SetInputWeight(0, 1f); }
    }

    void OnDestroy()
    {
        if (_graph.IsValid()) _graph.Destroy();
    }
}

