// 1) IJob：单任务并行（比如把一批点的颜色按亮度排序）
[BurstCompile]
public struct SaturateColorsJob : IJob
{
    public NativeArray<float4> colors;
    public float amount;

    public void Execute()
    {
        for (int i = 0; i < colors.Length; i++)
        {
            var c = colors[i];
            float3 rgb = c.xyz;
            float lum = math.dot(rgb, new float3(0.2126f, 0.7152f, 0.0722f));
            rgb = math.lerp(rgb, lum.xxx, amount);
            colors[i] = new float4(rgb, c.w);
        }
    }
}

// 2) IJobParallelFor：批量并行（比如大批量粒子位置更新）
[BurstCompile]
public struct UpdateParticlesJob : IJobParallelFor
{
    public NativeArray<float3> positions;
    public NativeArray<float3> velocities;
    public float dt;
    public float3 gravity;

    public void Execute(int i)
    {
        velocities[i] += gravity * dt;
        positions[i]  += velocities[i] * dt;
    }
}

// 3) 在主线程提交
public class JobDispatcher : MonoBehaviour
{
    NativeArray<float3> _pos, _vel;
    const int N = 10_000;

    void Start()
    {
        _pos = new NativeArray<float3>(N, Allocator.Persistent);
        _vel = new NativeArray<float3>(N, Allocator.Persistent);
        for (int i = 0; i < N; i++) { _pos[i] = i; _vel[i] = 0; }
    }

    void Update()
    {
        var job = new UpdateParticlesJob
        {
            positions = _pos,
            velocities = _vel,
            dt = Time.deltaTime,
            gravity = new float3(0, -9.8f, 0)
        };
        // 64 批次，调度到多核
        JobHandle handle = job.Schedule(N, 64);
        handle.Complete(); // 主线程同步
    }

    void OnDestroy()
    {
        if (_pos.IsCreated) _pos.Dispose();
        if (_vel.IsCreated) _vel.Dispose();
    }
}

