// 1) ComponentData：纯数据
public struct Velocity : IComponentData
{
    public float3 value;
}

public struct Lifetime : IComponentData
{
    public float remaining;
}

// 2) ISystem：每帧移动 + 寿命衰减
[BurstCompile]
public partial struct MoveSystem : ISystem
{
    [BurstCompile]
    public void OnCreate(ref SystemState s) { }
    [BurstCompile]
    public void OnDestroy(ref SystemState s) { }

    [BurstCompile]
    public void OnUpdate(ref SystemState s)
    {
        float dt = SystemAPI.Time.DeltaTime;
        // ISystem 自动迭代所有含 LocalTransform + Velocity 的 Entity
        foreach (var (transform, vel) in
                 SystemAPI.Query<RefRW<LocalTransform>, RefRO<Velocity>>())
        {
            transform.ValueRW.Position += vel.ValueRO.value * dt;
        }
        // 寿命衰减（IJobEntity 写法）
        new DecayLifeJob { dt = dt }.ScheduleParallel();
    }
}

[BurstCompile]
public partial struct DecayLifeJob : IJobEntity
{
    public float dt;
    public void Execute(Entity e, ref Lifetime l, EnabledRefRW<Lifetime> enabled)
    {
        l.remaining -= dt;
        if (l.remaining <= 0) enabled.ValueRW = false; // 启用组件 = false
    }
}

