    // 命令行：Unity -batchmode -nographics -quit -projectPath . -executeMethod BuildAutomation.BuildAndroid
    public static void BuildAndroid()
    {
        // 1) Build Addressables
        AddressableAssetSettings.CleanPlayerContent();
        AddressableAssetSettings.BuildPlayerContent(out var result);
        if (!string.IsNullOrEmpty(result.Error))
        {
            Debug.LogError("Addressables 构建失败：" + result.Error);
            EditorApplication.Exit(1);
            return;
        }

        // 2) Build Player
        EditorUserBuildSettings.SwitchActiveBuildTarget(BuildTargetGroup.Android, BuildTarget.Android);
        var opts = new BuildPlayerOptions
        {
            scenes = GetEnabledScenes(),
            locationPathName = "Build/Android/Game.aab",
            target = BuildTarget.Android,
            options = BuildOptions.None,
            targetGroup = BuildTargetGroup.Android
        };
        EditorUserBuildSettings.buildAppBundle = true;
        var report = BuildPipeline.BuildPlayer(opts);
        Debug.Log($"Build 结果 {report.summary.result}，大小 {report.summary.totalSize / 1024 / 1024} MB");
        EditorApplication.Exit(report.summary.result == BuildResult.Succeeded ? 0 : 1);
    }

    static string[] GetEnabledScenes()
    {
        var list = new System.Collections.Generic.List<string>();
        foreach (var s in EditorBuildSettings.scenes)
            if (s.enabled) list.Add(s.path);
        return list.ToArray();
