public class DamageCalculator
{
    System.Random _rng;
    public DamageCalculator(int seed = 0) { _rng = new System.Random(seed); }
    public int Calculate(float baseDmg, float critChance, float critMult)
    {
        return _rng.NextDouble() < critChance
            ? Mathf.RoundToInt(baseDmg * critMult)
            : Mathf.RoundToInt(baseDmg);
    }
}

