// 自定义 PropertyDrawer：[MinMaxSlider]
using UnityEditor;
using UnityEngine;

public class MinMaxSliderAttribute : PropertyAttribute
{
    public float min, max;
    public MinMaxSliderAttribute(float min, float max) { this.min = min; this.max = max; }
}

[CustomPropertyDrawer(typeof(MinMaxSliderAttribute))]
public class MinMaxSliderDrawer : PropertyDrawer
{
    public override void OnGUI(Rect pos, SerializedProperty prop, GUIContent label)
    {
        var attr = (MinMaxSliderAttribute)attribute;
        EditorGUI.Slider(
            new Rect(pos.x, pos.y, pos.width, EditorGUIUtility.singleLineHeight),
            prop, attr.min, attr.max, label);
    }
}

// 用法
public class EnemySpawner : MonoBehaviour
{
    [MinMaxSlider(0f, 60f)]
    public float spawnInterval;
}
